// Output: items[0].json = { replyToken, messages: Array<{type:"text", text:string}> }

// ---------- utilities ----------
function sanitizeForJsonAndLine(raw) {
  let s = (raw ?? "").toString();

  // Remove BOM
  s = s.replace(/\uFEFF/g, "");

  // Normalize Unicode
  s = s.normalize("NFC");

  // Drop control chars (เว้น \n \r \t)
  s = s.replace(/[\u0000-\u0008\u000B-\u000C\u000E-\u001F\u007F]/g, "");

  // Remove fenced code ```...``` → คง inner
  s = s.replace(/```[\s\S]*?```/g, (m) => {
    const inner = m.replace(/```/g, "").trim();
    return inner ? `\n${inner}\n` : "";
  });

  // Remove inline `code`
  s = s.replace(/`([^`]+)`/g, "$1");

  // Strip HTML
  s = s.replace(/<\/?[^>]+>/g, "");

  // Normalize newline & blank lines
  s = s.replace(/\r\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();

  // Bullet normalize
  s = s.replace(/^\s*-\s+/gm, "• ");

  // Escape U+2028/U+2029 (กัน parser บางตัว)
  s = s.replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');

  // Fix unpaired surrogates → �
  s = s.replace(
    /([\uD800-\uDBFF])(?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])([\uDC00-\uDFFF])/g,
    "�"
  );

  return s;
}

function splitGraphemes(str) {
  if (typeof Intl !== "undefined" && Intl.Segmenter) {
    const seg = new Intl.Segmenter("th", { granularity: "grapheme" });
    return Array.from(seg.segment(str), s => s.segment);
  }
  return Array.from(str); // fallback (UTF-16 code units)
}

// เพดานต่อข้อความ: ใช้ 4,800 (< 5,000 ของ LINE) เพื่อเผื่อ margin
const MAX_PER_MESSAGE = 4800;

function chunkByGrapheme(text, limit = MAX_PER_MESSAGE) {
  const g = splitGraphemes(text);
  const chunks = [];
  let buf = [];
  let len = 0;
  for (const ch of g) {
    const chLen = ch.length; // UTF-16 code units
    if (len + chLen > limit) {
      if (buf.length) chunks.push(buf.join(""));
      buf = [ch];
      len = chLen;
    } else {
      buf.push(ch);
      len += chLen;
    }
  }
  if (buf.length) chunks.push(buf.join(""));
  return chunks;
}

function packIntoAtMostFive(chunks, perLimit = MAX_PER_MESSAGE) {
  if (chunks.length === 0) return [];
  if (chunks.length <= 5) return chunks;

  const packed = [];
  let cur = "";
  for (const piece of chunks) {
    if (piece.length > perLimit) {
      const re = chunkByGrapheme(piece, perLimit);
      for (const r of re) {
        if (!cur) cur = r;
        else if (cur.length + 1 + r.length <= perLimit) cur += "\n" + r;
        else { packed.push(cur); cur = r; }
      }
      continue;
    }
    if (!cur) cur = piece;
    else if (cur.length + 1 + piece.length <= perLimit) cur += "\n" + piece;
    else { packed.push(cur); cur = piece; }
  }
  if (cur) packed.push(cur);

  // ยืดเพดานแบบ adaptive (แต่ไม่เกิน 5000) หากยัง >5
  while (packed.length > 5) {
    const totalLen = packed.reduce((s, x) => s + x.length, 0);
    const adaptive = Math.min(5000, Math.ceil(totalLen / 5) + 100);
    if (adaptive <= perLimit) break;

    const re = [];
    let cur2 = "";
    for (const p of packed) {
      for (const block of p.split("\n")) {
        if (!block) continue;
        if (!cur2) cur2 = block;
        else if (cur2.length + 1 + block.length <= adaptive) cur2 += "\n" + block;
        else { re.push(cur2); cur2 = block; }
      }
    }
    if (cur2) re.push(cur2);
    if (re.length >= packed.length) break;
    packed.splice(0, packed.length, ...re);
    perLimit = adaptive;
  }

  if (packed.length > 5) {
    const sliced = packed.slice(0, 4);
    const trimmedCount = packed.length - 4;
    const notice = `…(ตัดข้อความออก ${trimmedCount} ชิ้นเพื่อให้สอดคล้องกับข้อจำกัดการส่งของ LINE)`;
    const rest = packed.slice(4).join("\n\n");
    const last = (notice + "\n\n" + rest).slice(0, 5000);
    sliced.push(last);
    return sliced;
  }
  return packed;
}

// ---------- คำนวณขนาด UTF-8 โดยไม่ใช้ TextEncoder ----------
function utf8ByteLength(str) {
  // เดินตาม "code point" ด้วย for...of (ES6) ปลอดภัยต่อ surrogate pair
  let bytes = 0;
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp <= 0x7F) bytes += 1;
    else if (cp <= 0x7FF) bytes += 2;
    else if (cp <= 0xFFFF) bytes += 3;
    else bytes += 4;
  }
  return bytes;
}

// ---------- ดึงข้อมูลจาก node อื่น (Code v2) ----------
function getItemFrom(nodeName) {
  const arr = $items(nodeName, 0, 0);
  return (arr && arr[0]) ? arr[0].json : {};
}

const jEdit = getItemFrom("Edit Fields"); // { message, replyToken, userid }
const jAI   = getItemFrom("AI Agent");    // อาจมี { output/text/result/content }

// 1) เลือกแหล่งข้อความ (AI ก่อน, ไม่งั้นใช้ข้อความผู้ใช้)
const sourceText = (
  jAI.output ?? jAI.text ?? jAI.result ?? jAI.content ?? jEdit.message ?? ""
).toString();

// 2) sanitize → JSON-safe
const cleaned = sanitizeForJsonAndLine(sourceText);

// 3) chunk + pack ≤ 5
const rough = chunkByGrapheme(cleaned, MAX_PER_MESSAGE);
const parts = packIntoAtMostFive(rough, MAX_PER_MESSAGE);

// 4) fallback: ห้ามว่าง
const safeParts = (Array.isArray(parts) && parts.length > 0)
  ? parts
  : ["(ไม่มีข้อความจากระบบ จึงตอบกลับค่าเริ่มต้น)"];

// 5) guard ขนาด request โดยประมาณ (เผื่อ limit 2MB)
const preview = safeParts.join("\n\n");
if (utf8ByteLength(preview) > 1_800_000) {
  const short = preview.slice(0, 300_000) + "\n\n…(ตัดเนื้อหาเนื่องจากขนาดเกินกำหนด)";
  const shortParts = packIntoAtMostFive(chunkByGrapheme(short, MAX_PER_MESSAGE), MAX_PER_MESSAGE);
  const messages = shortParts.map(p => ({ type: "text", text: p }));
  return [{ json: { replyToken: jEdit.replyToken, messages } }];
}

// 6) messages array + ตรวจ serialize ล่วงหน้า
const messages = safeParts.map(p => ({ type: "text", text: p }));
try {
  JSON.stringify({ replyToken: jEdit.replyToken, messages });
} catch {
  const fallback = "(ไม่สามารถแปลงเป็น JSON ได้ จึงส่งข้อความย่อแทน)";
  return [{ json: { replyToken: jEdit.replyToken, messages: [{ type: "text", text: fallback }] } }];
}

return [{ json: { replyToken: jEdit.replyToken, messages } }];
